package com.renthouse.operation;import com.renthouse.auth.*;import com.renthouse.common.api.*;import com.renthouse.operation.service.DashboardService;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/landlord/dashboard")public class DashboardController{private final DashboardService s;public DashboardController(DashboardService s){this.s=s;}@GetMapping public ApiResponse<Data>get(){CurrentUser.requireRole(UserRole.LANDLORD);long id=CurrentUser.require().id();return ApiResponse.ok(s.getDashboardData(id));}public record Data(long vacantUnits,long occupiedUnits,long pendingAppointments){}}
